// Package modelcatalog reads the shared pi-ai provider catalog generated by
// scripts/generate-model-catalog.ts. It is the desktop client's only source of
// built-in provider and model IDs.
package modelcatalog

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/deskwand/bot/desktop/internal/i18n"
)

// The embedded copy is asserted byte-identical to the repository contract by
// catalog_test.go. The desktop binary must validate without repository files.
//
//go:embed model-catalog.json
var embeddedCatalog []byte

// Model is one chat model listed by a built-in provider.
type Model struct {
	ID            string   `json:"id"`
	Name          string   `json:"name"`
	API           string   `json:"api"`
	BaseURL       string   `json:"baseUrl"`
	Input         []string `json:"input,omitempty"`
	ContextWindow int      `json:"contextWindow"`
	// ThinkingLevels is what pi offers for this model; absent means there is
	// nothing to choose (the model does not reason).
	ThinkingLevels []string `json:"thinkingLevels,omitempty"`
}

// Provider is one built-in provider from the shared catalog.
type Provider struct {
	ID      string  `json:"id"`
	Name    string  `json:"name"`
	Keyless bool    `json:"keyless,omitempty"`
	Models  []Model `json:"models"`
}

type catalog struct {
	SchemaVersion int        `json:"schemaVersion"`
	Providers     []Provider `json:"providers"`
}

// CustomModel is one model declared by a deployment's custom provider.
type CustomModel struct {
	ID            string `json:"id"`
	ContextWindow int    `json:"contextWindow,omitempty"`
	MaxTokens     int    `json:"maxTokens,omitempty"`
}

// CustomProvider is an OpenAI- or Anthropic-compatible endpoint declared by a
// deployment.
type CustomProvider struct {
	ID      string        `json:"id"`
	Name    string        `json:"name,omitempty"`
	API     string        `json:"api"`
	BaseURL string        `json:"baseUrl"`
	Models  []CustomModel `json:"models"`
}

// RoleRef identifies the provider and model a role uses.
type RoleRef struct {
	Provider string `json:"provider"`
	ID       string `json:"id"`
}

// ModelsDoc is the subset of DESKWAND_CONFIG.models that matters to the
// desktop client.
type ModelsDoc struct {
	Butler          RoleRef          `json:"butler"`
	Task            RoleRef          `json:"task"`
	CustomProviders []CustomProvider `json:"customProviders,omitempty"`
}

var builtin = mustCatalog()

func mustCatalog() catalog {
	var parsed catalog
	if err := json.Unmarshal(embeddedCatalog, &parsed); err != nil {
		panic("modelcatalog: parse embedded catalog: " + err.Error())
	}
	return parsed
}

// Builtin returns the providers in the shared catalog.
func Builtin() []Provider {
	return builtin.Providers
}

// LookupBuiltin finds a provider by ID.
func LookupBuiltin(id string) (Provider, bool) {
	for _, provider := range builtin.Providers {
		if provider.ID == id {
			return provider, true
		}
	}
	return Provider{}, false
}

// SecretNameFor derives the MODEL_KEY_* secret name for a provider ID.
func SecretNameFor(id string) string {
	return "MODEL_KEY_" + strings.ToUpper(strings.ReplaceAll(id, "-", "_"))
}

// IsKeyless reports whether a built-in provider authenticates without a
// MODEL_KEY_* secret.
func IsKeyless(id string) bool {
	provider, ok := LookupBuiltin(id)
	return ok && provider.Keyless
}

// ParseModels reads models and customProviders from one configuration
// document. The JSON-string form used by CLI and local dev is accepted too.
func ParseModels(configJSON []byte) (ModelsDoc, error) {
	var document struct {
		Models *ModelsDoc `json:"models"`
	}
	if err := json.Unmarshal(configJSON, &document); err != nil {
		var encoded string
		if stringErr := json.Unmarshal(configJSON, &encoded); stringErr != nil {
			return ModelsDoc{}, err
		}
		return ParseModels([]byte(encoded))
	}
	if document.Models == nil {
		var empty ModelsDoc
		return empty, nil
	}
	return *document.Models, nil
}

// ValidateModels applies the semantic rules that JSON schema cannot express.
// checkBuiltinModels is false during import and upgrade, when a configuration
// written against a newer pi-ai catalog must still be publishable.
func ValidateModels(locale string, doc ModelsDoc, checkBuiltinModels bool) error {
	custom := make(map[string]map[string]bool, len(doc.CustomProviders))
	for _, provider := range doc.CustomProviders {
		if _, ok := LookupBuiltin(provider.ID); ok {
			return fmt.Errorf("custom provider %q conflicts with a built-in provider", provider.ID)
		}
		if _, ok := custom[provider.ID]; ok {
			return fmt.Errorf("custom provider %q is declared more than once", provider.ID)
		}
		models := make(map[string]bool, len(provider.Models))
		for _, model := range provider.Models {
			if models[model.ID] {
				return fmt.Errorf("custom provider %q declares model %q more than once", provider.ID, model.ID)
			}
			models[model.ID] = true
		}
		custom[provider.ID] = models
	}

	if err := validateRole(locale, "butler", doc.Butler, custom, checkBuiltinModels); err != nil {
		return err
	}
	return validateRole(locale, "task", doc.Task, custom, checkBuiltinModels)
}

func validateRole(locale, role string, ref RoleRef, custom map[string]map[string]bool, checkBuiltinModels bool) error {
	if models, ok := custom[ref.Provider]; ok {
		if !models[ref.ID] {
			return fmt.Errorf("models.%s references model %q that custom provider %q does not declare", role, ref.ID, ref.Provider)
		}
		return nil
	}
	provider, ok := LookupBuiltin(ref.Provider)
	if !ok {
		return fmt.Errorf("models.%s references unknown provider %q", role, ref.Provider)
	}
	if !checkBuiltinModels {
		return nil
	}
	for _, model := range provider.Models {
		if model.ID == ref.ID {
			return nil
		}
	}
	return fmt.Errorf("%s", i18n.T(locale, "catalog.modelUnavailable", ref.Provider, ref.ID))
}

// ContextWindow resolves the Worker token limit; zero means the model is unknown.
// Custom models default to 128000, matching src/llm/models.ts.
func ContextWindow(doc ModelsDoc, ref RoleRef) int {
	for _, provider := range doc.CustomProviders {
		if provider.ID != ref.Provider {
			continue
		}
		for _, model := range provider.Models {
			if model.ID == ref.ID {
				if model.ContextWindow == 0 {
					return 128000
				}
				return model.ContextWindow
			}
		}
		return 0
	}
	if provider, ok := LookupBuiltin(ref.Provider); ok {
		for _, model := range provider.Models {
			if model.ID == ref.ID {
				return model.ContextWindow
			}
		}
	}
	return 0
}

// RequiredSecretNames returns the sorted, deduplicated MODEL_KEY_* names the
// butler and task roles require.
func RequiredSecretNames(doc ModelsDoc) []string {
	seen := map[string]bool{}
	for _, ref := range []RoleRef{doc.Butler, doc.Task} {
		if ref.Provider == "" || IsKeyless(ref.Provider) {
			continue
		}
		seen[SecretNameFor(ref.Provider)] = true
	}
	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}
